CREATE DATABASE IF NOT EXISTS driveflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE driveflow;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'ADMIN', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(120) NOT NULL, email VARCHAR(160) UNIQUE, phone VARCHAR(30) NOT NULL, license_number VARCHAR(80) NOT NULL UNIQUE, address VARCHAR(255), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_customer_name(full_name));
CREATE TABLE IF NOT EXISTS vehicles (id BIGINT PRIMARY KEY AUTO_INCREMENT, registration_number VARCHAR(30) NOT NULL UNIQUE, make VARCHAR(80) NOT NULL, model VARCHAR(80) NOT NULL, vehicle_type VARCHAR(50) NOT NULL, model_year SMALLINT, daily_rate DECIMAL(10,2) NOT NULL, status ENUM('AVAILABLE','RENTED','MAINTENANCE','INACTIVE') NOT NULL DEFAULT 'AVAILABLE', notes VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_vehicle_status(status));
CREATE TABLE IF NOT EXISTS rentals (id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT NOT NULL, vehicle_id BIGINT NOT NULL, start_date DATE NOT NULL, expected_return_date DATE NOT NULL, actual_return_date DATE NULL, daily_rate DECIMAL(10,2) NOT NULL, estimated_total DECIMAL(12,2) NOT NULL, final_total DECIMAL(12,2) NULL, status ENUM('BOOKED','ACTIVE','COMPLETED','CANCELLED') NOT NULL DEFAULT 'BOOKED', notes VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_rental_customer FOREIGN KEY(customer_id) REFERENCES customers(id), CONSTRAINT fk_rental_vehicle FOREIGN KEY(vehicle_id) REFERENCES vehicles(id), INDEX idx_rental_dates(vehicle_id,start_date,expected_return_date), INDEX idx_rental_status(status), CHECK(expected_return_date >= start_date));
CREATE TABLE IF NOT EXISTS payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, rental_id BIGINT NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_method ENUM('CASH','CARD','UPI','BANK_TRANSFER','OTHER') NOT NULL, reference_number VARCHAR(100), notes VARCHAR(255), paid_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_payment_rental FOREIGN KEY(rental_id) REFERENCES rentals(id), CHECK(amount > 0), INDEX idx_payment_rental(rental_id));
